def merge_routes(instance, routes):
    # Simple heuristic to merge routes
    merged_routes = []
    for route in routes:
        if not merged_routes:
            merged_routes.append(route)
        else:
            best_merge_index = -1
            best_merge_distance = float('inf')
            for i, merged_route in enumerate(merged_routes):
                # Try to merge at the end of the merged route
                end_to_start_distance = distance(instance.node_map[merged_route[-1]], instance.node_map[route[0]])
                if end_to_start_distance < best_merge_distance:
                    best_merge_distance = end_to_start_distance
                    best_merge_index = i
                # Try to merge at the start of the merged route
                start_to_end_distance = distance(instance.node_map[route[-1]], instance.node_map[merged_route[0]])
                if start_to_end_distance < best_merge_distance:
                    best_merge_distance = start_to_end_distance
                    best_merge_index = i
                    route.reverse()
            if best_merge_index != -1:
                merged_routes[best_merge_index].extend(route)
            else:
                merged_routes.append(route)
    return merged_routes

