    # Sort routes by length to try to merge shorter routes first
    routes.sort(key=len)
    optimized_routes = []
    unassigned_customers = set(instance.customer_ids)

    for route in routes:
        if all(cid in unassigned_customers for cid in route[1:-1]):
            optimized_routes.append(route)
            unassigned_customers -= set(route[1:-1])
        else:
